#include <algorithm>
#include <fstream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, length; in >> n >> length;
    vector<int> knots(n);
    for (int& x : knots) in >> x;
    sort(knots.begin(), knots.end());
    int answer = 0;
    // q is twice the fold position; endpoints are excluded.
    for (int q = 1; q < 2 * length; ++q) {
        bool valid = true;
        for (int x : knots) {
            int reflected = q - x;
            if (0 <= reflected && reflected <= length &&
                !binary_search(knots.begin(), knots.end(), reflected)) {
                valid = false; break;
            }
        }
        if (valid) ++answer;
    }
    out << answer << '\n';
}
int main() {
    ifstream in("folding.in"); ofstream out("folding.out");
    solve(in, out);
    return 0;
}
