#include <algorithm>
#include <fstream>
#include <vector>
using namespace std;
struct Rectangle { int left, right, bottom, top; };
void solve(istream& in, ostream& out) {
    int n; in >> n;
    vector<Rectangle> rectangles;
    vector<int> xs, ys;
    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2; in >> x1 >> y1 >> x2 >> y2;
        Rectangle r = {min(x1, x2), max(x1, x2), min(y1, y2), max(y1, y2)};
        rectangles.push_back(r);
        xs.push_back(r.left); xs.push_back(r.right);
        ys.push_back(r.bottom); ys.push_back(r.top);
    }
    sort(xs.begin(), xs.end()); xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end()); ys.erase(unique(ys.begin(), ys.end()), ys.end());
    long long area = 0;
    for (size_t i = 0; i + 1 < xs.size(); ++i) {
        for (size_t j = 0; j + 1 < ys.size(); ++j) {
            bool covered = false;
            for (const Rectangle& r : rectangles) {
                if (r.left <= xs[i] && xs[i + 1] <= r.right &&
                    r.bottom <= ys[j] && ys[j + 1] <= r.top) {
                    covered = true; break;
                }
            }
            if (covered) area += (long long)(xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
        }
    }
    out << area << '\n';
}
int main() {
    ifstream in("planting.in"); ofstream out("planting.out");
    solve(in, out);
    return 0;
}
