#include <fstream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    long long position; in >> position;
    vector<long long> length(1, 3);
    while (length.back() < position) {
        long long level = (long long)length.size();
        length.push_back(2 * length.back() + level + 3);
    }
    int level = (int)length.size() - 1;
    while (level > 0) {
        long long previous = length[level - 1];
        long long middle = level + 3;
        if (position <= previous) {
            --level;
        } else if (position <= previous + middle) {
            out << (position == previous + 1 ? 'm' : 'o') << '\n';
            return;
        } else {
            position -= previous + middle;
            --level;
        }
    }
    out << (position == 1 ? 'm' : 'o') << '\n';
}
int main() {
    ifstream in("moo.in"); ofstream out("moo.out");
    solve(in, out);
    return 0;
}
